INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('e39cd0a4-cf53-4225-a571-a20cf371735c','sirket-kurulusu','Kosova''da Şirket Kuruluşu','Yabancı girişimciler için Kosova''da hızlı, eksiksiz ve uçtan uca şirket kuruluşu — çoğu dosya birkaç iş günü içinde.','Kosova, düşük vergi oranları, sade bürokrasisi ve hızlı kuruluş süreçleriyle yabancı girişimciler için Avrupa''nın en cazip merkezlerinden biri. En yaygın şirket türü olan limited şirket (SH.P.K. / LLC) için yasal asgari sermaye şartı simgesel düzeydedir (çoğu durumda 1 €), bu da düşük maliyetle başlamayı mümkün kılar. Şirketinizi genellikle birkaç iş günü içinde, tüm resmi adımları sizin adınıza yöneterek kuruyoruz.'||char(10)||''||char(10)||'## Nasıl çalışıyoruz?'||char(10)||''||char(10)||'Önce iş modelinize en uygun şirket türünü belirliyoruz: tek kişilik işletmeden limited şirkete (SH.P.K.), anonim şirkete (SH.A.) veya şube/temsilcilik yapısına kadar. Ardından isim tespitini yapıyor, kuruluş sözleşmesini hazırlıyor ve Kosova İş Kayıt Ajansı (ARBK / KBRA) nezdinde tescili tamamlıyoruz. Tescil ile birlikte şirketiniz tüzel kişilik kazanır, işletme numarası ve fiskal numarasını alır.'||char(10)||''||char(10)||'## Kuruluş adımları'||char(10)||''||char(10)||'- Şirket türü, ortaklık yapısı ve isim tespiti'||char(10)||''||char(10)||'- Kuruluş sözleşmesi ve gerekli beyanların hazırlanması'||char(10)||''||char(10)||'- ARBK (KBRA) ticaret sicili tescili ve işletme/fiskal numara'||char(10)||''||char(10)||'- Faaliyete göre KDV kaydı (yasal eşik üzeri ciro beklentisinde)'||char(10)||''||char(10)||'- Kurumsal banka hesabının açılması'||char(10)||''||char(10)||'## Kuruluştan sonra da yanınızdayız'||char(10)||''||char(10)||'Kuruluş tek başına yeterli değildir, şirketinizi ayakta tutan süreçleri de devralıyoruz: aylık muhasebe ve vergi kaydının devreye alınması, çalışan ve oturum izni süreçleriyle entegrasyon, resmi yazışmalar ve yıllık yükümlülüklerin takibi. Kosova''da fiziken bulunmanıza gerek kalmadan süreci vekaletle yürütebiliriz.'||char(10)||''||char(10)||'600''den fazla şirketi başarıyla kurduğumuz tecrübeyle, sürecin her adımında tek muhatabınız biziz. Not: Süreler, ücretler ve mevzuat şartları güncel düzenlemelere göre değişebilir, dosyanıza özel güncel bilgiyi ön görüşmede netleştiriyoruz.','Building2','İş modeline uygun şirket türü (SH.P.K. / LLC) ve isim tespiti'||char(10)||'ARBK (KBRA — Ticaret Sicili) tescili ve işletme numarası'||char(10)||'Fiskal numara ve gerektiğinde KDV kaydı'||char(10)||'Kurumsal banka hesabı açılışında rehberlik'||char(10)||'Resmi adres, kuruluş sözleşmesi ve vekaletle temsil',1,1,1791934490308,1791934490308);
INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('b25ecbbb-cec6-42fa-94a1-3b614e5615d7','oturum-calisma-izni','Oturum & Çalışma İzni','Kosova''da oturum ve çalışma izni başvurularında eksiksiz dosya, doğru belge ve uçtan uca takip.','Kosova''da yaşamak ve çalışmak için gereken oturum ve çalışma izni süreçlerini sizin için baştan sona yönetiyoruz. Eksik belge, hatalı başvuru veya kaçırılan süreler kaynaklı gecikmelerin önüne geçerek dosyanızı ilk seferde doğru hazırlıyoruz.'||char(10)||''||char(10)||'## Kimler başvurabilir?'||char(10)||''||char(10)||'İster şirket ortağı veya yatırımcı, ister bir işveren nezdinde çalışan, ister aile birleşimi yoluyla, durumunuza en uygun oturum türünü belirliyor ve gerekçenize göre dosyanızı kurguluyoruz. Kosova''da şirket sahibi olmak, oturum için en yaygın ve istikrarlı gerekçelerden biridir.'||char(10)||''||char(10)||'## Genel süreç'||char(10)||''||char(10)||'- Kosova''ya giriş sonrası yasal süre içinde yerel polise adres/konaklama kaydı'||char(10)||''||char(10)||'- Oturum gerekçesine uygun belgelerin toplanması, tercümesi ve noter onayı'||char(10)||''||char(10)||'- Göç ve Yabancılar Dairesi''ne başvurunun yapılması ve randevu yönetimi'||char(10)||''||char(10)||'- Oturum ile birlikte çalışma izni (birleşik izin) sürecinin yürütülmesi'||char(10)||''||char(10)||'- Sonuçlanana kadar takip ve yıllık yenilemelerin zamanında yapılması'||char(10)||''||char(10)||'## Sık gereken belgeler'||char(10)||''||char(10)||'Pasaport ve kopyası, biyometrik fotoğraf, geçerli sağlık sigortası, konaklama/adres belgesi, adli sicil kaydı ve oturum gerekçenizi kanıtlayan belgeler (şirket tescili, iş sözleşmesi veya aile bağını gösteren evraklar) genellikle istenir. Gerekli belgeler başvuru türüne ve güncel mevzuata göre değişebilir.'||char(10)||''||char(10)||'## Neden biz?'||char(10)||''||char(10)||'820''den fazla başarılı oturum başvurusu tecrübesi, güncel mevzuat ve kurum süreçlerine hâkimiyet, belge/tercüme/noter işlemlerinde tam destek. Randevularınızı planlıyor, kurumlarla iletişimi sizin adınıza yürütüyoruz. Not: Süreçler ve belge listeleri resmî düzenlemelere göre değişebilir, dosyanıza özel durumu ön görüşmede netleştiriyoruz.','Plane','Oturum izni ilk başvuru ve yıllık yenileme'||char(10)||'Çalışma izni (tek izin / birleşik izin) süreçleri'||char(10)||'Şirket ortağı ve yatırımcı bazlı oturum'||char(10)||'Aile birleşimi başvuruları'||char(10)||'Belge hazırlama, tercüme ve noter işlemleri'||char(10)||'Adres/polis kaydı, randevu ve başvuru takibi',2,1,1791934490308,1791934490308);
INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('90ae59cb-88e9-4738-a798-58c59ecae438','muhasebe-vergi','Muhasebe & Vergi','Kosova''da aylık muhasebe, beyannameler ve vergi danışmanlığında mevzuata tam uyum ve zamanında bildirim.','Şirketinizin Kosova''daki tüm muhasebe ve vergi yükümlülüklerini üstleniyoruz. Böylece siz işinize odaklanırken, bildirimlerinizin zamanında, eksiksiz ve doğru yapıldığından emin olursunuz.'||char(10)||''||char(10)||'## Kosova vergi sisteminin avantajı'||char(10)||''||char(10)||'Kosova, bölgenin en rekabetçi vergi sistemlerinden birine sahiptir. Güncel uygulamada kurumlar vergisi genel olarak %10 düzeyinde, standart KDV oranı %18 (temel bazı ürün/hizmetlerde indirimli oran uygulanır) ve KDV mükellefiyeti için yıllık ciro eşiği 30.000 € civarındadır. Bu oranlar ve eşikler resmî mevzuata göre değişebilir, güncel durumu şirketinize özel değerlendiriyoruz.'||char(10)||''||char(10)||'## Hizmet kapsamı'||char(10)||''||char(10)||'- Aylık muhasebe kayıtları ve defter tutma'||char(10)||''||char(10)||'- KDV beyannameleri ve kurumlar/gelir vergisi bildirimleri'||char(10)||''||char(10)||'- Bordro, maaş hesaplama ve çalışan sosyal güvenlik bildirimleri'||char(10)||''||char(10)||'- Aylık/dönemsel finansal raporlama ve yöneticiye özel özetler'||char(10)||''||char(10)||'- Vergi planlaması ve mevzuat değişikliklerine uyum'||char(10)||''||char(10)||'## Avantajınız'||char(10)||''||char(10)||'Kosova''nın düşük vergi oranlarından yasal yollarla en iyi şekilde yararlanırsınız, zamanında bildirim sayesinde ceza ve gecikme faizi riskini ortadan kaldırırsınız, anlaşılır raporlarla şirketinizin finansal durumunu her zaman net görürsünüz.'||char(10)||''||char(10)||'Düzenli bilgilendirme ve şeffaf çalışma biçimiyle sürprizlerle karşılaşmazsınız. Not: Vergi oran ve eşikleri güncel mevzuata göre değişebilir, bağlayıcı bilgi için güncel resmî düzenlemeler esas alınır.','Calculator','Aylık muhasebe ve defter tutma'||char(10)||'KDV ve kurumlar/gelir vergisi beyannameleri'||char(10)||'Bordro, maaş ve çalışan (sosyal güvenlik) bildirimleri'||char(10)||'Finansal raporlama ve yönetici özetleri'||char(10)||'Vergi planlaması ve uyum danışmanlığı'||char(10)||'Resmî yazışma ve denetim süreçlerinde destek',3,1,1791934490308,1791934490308);
INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('f3676161-4690-42bd-9ac1-b3b22cf3314e','yatirim-is-danismanligi','Yatırım & İş Danışmanlığı','Kosova pazarına giriş, yatırım ve büyüme stratejilerinde saha tecrübesine dayalı yerel uzmanlık.','Kosova''da yatırım yapmayı veya işinizi büyütmeyi mi planlıyorsunuz? Avrupa''nın en genç nüfuslarından birine, nitelikli ve uygun maliyetli iş gücüne ve Balkanlar''ın merkezinde stratejik bir konuma sahip bu pazarda, yerel saha tecrübemizle doğru kararları doğru zamanda almanıza yardımcı oluyoruz.'||char(10)||''||char(10)||'## Neler sunuyoruz?'||char(10)||''||char(10)||'Pazar ve sektör analizinden fizibilite çalışmasına, yatırım teşvikleri ve maliyet avantajlarının değerlendirilmesinden yerel ortaklık, tedarikçi ve kurum bağlantılarına kadar, Kosova''da iş yapmanın tüm pratik boyutlarında yanınızdayız. Ofis/lokasyon seçimi, operasyon kurulumu ve ekip oluşturma gibi uygulama adımlarını da birlikte planlıyoruz.'||char(10)||''||char(10)||'## Kimler için?'||char(10)||''||char(10)||'- Kosova pazarına ilk kez açılmak isteyen yabancı şirketler'||char(10)||''||char(10)||'- Yeni bir yatırım fırsatını değerlendiren girişimciler'||char(10)||''||char(10)||'- Mevcut işini büyütmek veya operasyonunu optimize etmek isteyen şirketler'||char(10)||''||char(10)||'## Çalışma biçimimiz'||char(10)||''||char(10)||'İlk görüşmede hedeflerinizi ve beklentilerinizi dinliyor, ardından size özel bir yol haritası çıkarıyoruz. Şirket kuruluşundan oturum/çalışma izinlerine, muhasebeden operasyona kadar diğer hizmetlerimizle entegre çalışarak tek elden ilerlemenizi sağlıyoruz.'||char(10)||''||char(10)||'Not: Pazar koşulları, teşvikler ve mevzuat zaman içinde değişebilir, kararlarınızı güncel ve dosyanıza özel verilerle destekliyoruz.','TrendingUp','Pazara giriş ve yerleşme stratejisi'||char(10)||'Sektör, rekabet ve fizibilite analizi'||char(10)||'Yatırım teşvikleri ve fırsatların değerlendirilmesi'||char(10)||'Yerel ortak, tedarikçi ve kurum bağlantıları'||char(10)||'Ofis/lokasyon ve operasyon kurulumu'||char(10)||'Büyüme, ölçekleme ve risk yönetimi danışmanlığı',4,1,1791934490308,1791934490308);
INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('6ff6778c-36cc-40ab-a902-146ec016958e','soy-bagi-ile-vatandaslik','Soy Bağı ile Vatandaşlık','Soy bağınızı kanıtlayarak vatandaşlık kazanma sürecinde uygunluk analizinden başvuruya uçtan uca rehberlik.','Atalarınızdan gelen soy bağınız yeni bir vatandaşlık için kapı açabilir. Hangi belgelerin gerektiğini, sürecin nasıl işlediğini ve uygunluk şartlarını sizin için baştan sona yönetiyor, dağınık arşiv ve nüfus kayıtlarını bir araya getirerek güçlü bir başvuru dosyası oluşturuyoruz.'||char(10)||''||char(10)||'## Süreç nasıl işliyor?'||char(10)||''||char(10)||'Önce soy bağınızı ve uygunluğunuzu değerlendiriyoruz, hangi kuşağa ve hangi belgelere dayanarak başvurabileceğinizi netleştiriyoruz. Ardından gereken nüfus, tapu ve arşiv kayıtlarını araştırıp belgeleri eksiksiz topluyor, tasdikli tercüme ve noter işlemlerini tamamlayıp başvuruyu yapıyoruz.'||char(10)||''||char(10)||'## Hizmet kapsamı'||char(10)||''||char(10)||'- Soy bağı ve uygunluk analizi (ön değerlendirme)'||char(10)||''||char(10)||'- Nüfus kayıtları, tapu ve devlet arşivi araştırması'||char(10)||''||char(10)||'- Belge toplama, tasdikli tercüme ve noter onayı'||char(10)||''||char(10)||'- Başvuru dosyasının hazırlanması ve resmî kurumlara sunulması'||char(10)||''||char(10)||'- Randevu yönetimi ve sonuca kadar takip'||char(10)||''||char(10)||'## Neden profesyonel destek?'||char(10)||''||char(10)||'Soy bağına dayalı başvurularda en büyük zorluk, onlarca yıl öncesine ait kayıtların bulunması, doğru tasdiklenmesi ve resmî formata uygun sunulmasıdır. Tek bir eksik veya hatalı belge süreci aylarca uzatabilir. Uçtan uca takiple bu riskleri en aza indiriyoruz.'||char(10)||''||char(10)||'Durumunuzu değerlendirmek için ücretsiz ön görüşme talep edebilirsiniz. Not: Uygunluk şartları ve gerekli belgeler ilgili ülke mevzuatına ve her ailenin özel durumuna göre değişir, bağlayıcı değerlendirme dosya incelemesi sonrası yapılır.','Scale','Soy bağı ve uygunluk ön değerlendirmesi'||char(10)||'Nüfus, tapu ve arşiv kayıtlarının araştırılması'||char(10)||'Belge toplama, tasdikli tercüme ve noter işlemleri'||char(10)||'Başvuru dosyasının eksiksiz hazırlanması'||char(10)||'Resmî kurumlara başvuru ve randevu yönetimi'||char(10)||'Sonuçlanana kadar süreç takibi',5,1,1791934490308,1791934490308);
INSERT INTO "Post" ("id","slug","title","excerpt","content","author","category","published","publishedAt","createdAt","updatedAt") VALUES ('7b493612-7e46-4791-942c-0d797c218571','kosovada-sirket-nasil-kurulur','Kosova''da Şirket Nasıl Kurulur? Adım Adım Rehber','Yabancı girişimciler için Kosova''da şirket kuruluşunun adımları, gereken belgeler ve süreler.','Kosova, hızlı kuruluş süreçleri ve düşük vergi oranlarıyla yabancı girişimciler için cazip bir merkez. Peki süreç nasıl işliyor?'||char(10)||''||char(10)||'## 1. Şirket türünü ve ismi belirleyin'||char(10)||''||char(10)||'En yaygın tür, limited şirkete (SH.P.K. / LLC) karşılık gelen yapıdır. İş modelinize uygun türü seçip isim tespitini yapıyoruz.'||char(10)||''||char(10)||'## 2. ARBK tescili'||char(10)||''||char(10)||'Ticaret sicili (ARBK) nezdinde tescil ile şirketiniz tüzel kişilik kazanır ve fiskal numarasını alır.'||char(10)||''||char(10)||'## 3. Vergi ve KDV kaydı'||char(10)||''||char(10)||'Faaliyetinize göre KDV mükellefiyeti ve gerekli vergi kayıtları tamamlanır.'||char(10)||''||char(10)||'## 4. Banka hesabı ve muhasebe'||char(10)||''||char(10)||'- Kurumsal banka hesabının açılması'||char(10)||''||char(10)||'- Aylık muhasebe ve beyan süreçlerinin devreye alınması'||char(10)||''||char(10)||'Tüm bu adımları, Kosova''da bulunmanıza gerek kalmadan vekaletle sizin adınıza yürütebiliriz. Detaylı bilgi için bizimle görüşün.','ProKosova Solutions','Şirket Kuruluşu',1,1791934490308,1791934490308,1791934490308);
INSERT INTO "Post" ("id","slug","title","excerpt","content","author","category","published","publishedAt","createdAt","updatedAt") VALUES ('440cef4a-e8b4-457f-8821-195a5103c7db','kosovada-oturum-izni-sartlar-surec','Kosova''da Oturum İzni: Şartlar ve Süreç','Kosova''da oturum izni türleri, başvuru şartları ve sürecin doğru yönetimi.','Kosova''da yaşamak isteyen yabancılar için oturum izni, sürecin doğru yönetildiğinde oldukça akıcı ilerleyen bir aşamadır.'||char(10)||''||char(10)||'## Oturum türleri'||char(10)||''||char(10)||'Şirket ortaklığı, çalışma, aile birleşimi veya diğer gerekçelerle farklı oturum türleri mevcuttur. Durumunuza en uygun olanı birlikte belirleriz.'||char(10)||''||char(10)||'## Başvuru için genel adımlar'||char(10)||''||char(10)||'- Gerekli belgelerin hazırlanması ve tercüme/noter işlemleri'||char(10)||''||char(10)||'- Başvurunun yapılması ve randevu yönetimi'||char(10)||''||char(10)||'- Sonuçlanana kadar takip ve kurum iletişimi'||char(10)||''||char(10)||'## Sık yapılan hatalar'||char(10)||''||char(10)||'Eksik belge ve geç yapılan yenilemeler en sık karşılaşılan gecikme sebepleridir. 820''den fazla başarılı başvuru tecrübemizle bu riskleri ortadan kaldırıyoruz.'||char(10)||''||char(10)||'Oturum süreciniz için ücretsiz ön görüşme talep edebilirsiniz.','ProKosova Solutions','Oturum',1,1791934490308,1791934490308,1791934490308);
INSERT INTO "Post" ("id","slug","title","excerpt","content","author","category","published","publishedAt","createdAt","updatedAt") VALUES ('a856a8eb-bbf1-473b-b153-75e880f7075a','kosovada-vergi-sistemi-avantajlari','Kosova''da Vergi Sistemi ve Avantajları','Kosova''nın rekabetçi vergi oranları ve işletmelere sunduğu avantajlara genel bir bakış.','Kosova, bölgedeki en rekabetçi vergi sistemlerinden birine sahip. Bu da onu yabancı yatırımcılar için cazip kılan en önemli etkenlerden biri.'||char(10)||''||char(10)||'## Öne çıkan başlıklar'||char(10)||''||char(10)||'Kurumlar vergisi, gelir vergisi ve KDV oranları birçok Avrupa ülkesine kıyasla düşüktür. Ancak her işletmenin durumu farklı olduğundan, avantajlardan tam yararlanmak için doğru planlama şarttır.'||char(10)||''||char(10)||'## Nelere dikkat etmeli?'||char(10)||''||char(10)||'- Doğru vergi mükellefiyeti ve KDV kaydı'||char(10)||''||char(10)||'- Zamanında beyan ve ödeme'||char(10)||''||char(10)||'- Giderlerin doğru belgelenmesi'||char(10)||''||char(10)||'Muhasebe ekibimiz, işletmenize özel vergi planlamasını hazırlayarak yükümlülüklerinizi yasal sınırlar içinde optimize eder.','ProKosova Solutions','Vergi',1,1791934490308,1791934490308,1791934490308);
INSERT INTO "Post" ("id","slug","title","excerpt","content","author","category","published","publishedAt","createdAt","updatedAt") VALUES ('0c66d6dc-2eb6-4bec-9e04-5d4812dd6501','neden-kosovada-yatirim','Neden Kosova''da Yatırım? Yabancı Girişimciler İçin Fırsatlar','Genç nüfus, düşük maliyetler ve stratejik konum: Kosova''yı yatırım için cazip kılan nedenler.','Kosova, son yıllarda yabancı girişimcilerin radarına giren, potansiyeli yüksek bir pazar. Peki bu ilgiyi haklı çıkaran nedenler neler?'||char(10)||''||char(10)||'## Genç ve dinamik nüfus'||char(10)||''||char(10)||'Avrupa''nın en genç nüfuslarından birine sahip olan Kosova, nitelikli ve uygun maliyetli iş gücü sunar.'||char(10)||''||char(10)||'## Düşük maliyetler ve rekabetçi vergiler'||char(10)||''||char(10)||'İşletme maliyetleri ve vergi oranları, birçok Avrupa ülkesine göre belirgin biçimde düşüktür.'||char(10)||''||char(10)||'## Stratejik konum'||char(10)||''||char(10)||'- Balkanlar''ın merkezinde, Avrupa pazarlarına yakın'||char(10)||''||char(10)||'- Büyüyen hizmet ve teknoloji sektörleri'||char(10)||''||char(10)||'Doğru rehberlikle Kosova''da yatırım, hızlı ve güvenli biçimde hayata geçirilebilir. Fırsatları değerlendirmek için bizimle görüşün.','ProKosova Solutions','Yatırım',1,1791934490308,1791934490308,1791934490308);
INSERT INTO "TeamMember" ("id","name","title","bio","order","email","createdAt") VALUES ('55a2a600-f825-4b1e-8dbd-b65a08f3520a','Bülent BOZKURT','Kurucu & Baş Danışman','6 yılı aşkın süredir Kosova''da yabancı girişimci ve yatırımcılara danışmanlık veriyor, 600+ şirket kuruluşu ve 820+ oturum başvurusuna liderlik etti.',1,'bulent@prokosovasolutions.com',1791934490308);
